<script setup>
import {ref,watch,onMounted,computed} from 'vue'
import {useRouter} from 'vue-router'
import {useI18n} from 'vue-i18n'
import api from '@/api'
const router=useRouter(),{locale}=useI18n(),tr=(en,ar)=>locale.value==='ar'?ar:en
const tab=ref('pending'),search=ref(''),perPage=ref(15),page=ref(1),loading=ref(false),error=ref(''),records=ref([]),meta=ref({current_page:1,last_page:1,total:0})
let token=0
const lastPage=computed(()=>meta.value.last_page||1)
async function load(){const current=++token;loading.value=true;error.value='';try{const {data}=await api.get('/rent/bookings',{params:{tab:tab.value,search:search.value,per_page:perPage.value,page:page.value}});if(current!==token)return;records.value=data.data||[];meta.value={current_page:data.current_page||1,last_page:data.last_page||1,total:data.total||0}}catch(e){if(current===token)error.value=e.response?.data?.message||tr('Cannot load bookings','تعذر تحميل الحجوزات')}finally{if(current===token)loading.value=false}}
watch([tab,perPage],()=>{page.value=1;load()});watch(search,()=>{page.value=1;load()});watch(page,load);onMounted(load)
const client=b=>b.customer?.name||b.customer?.customer_name||b.customer_company?.name||b.customer_company?.company_name||'—'
</script>
<template><section class="bk-page" :dir="locale==='ar'?'rtl':'ltr'"><div class="bk-head"><h2>{{tr('Booking','الحجوزات')}}</h2><button class="bk-primary" @click="router.push('/rent/booking/create')">+ {{tr('New Booking','حجز جديد')}}</button></div><div class="bk-card"><nav class="bk-tabs"><button :class="{active:tab==='pending'}" @click="tab='pending'">{{tr('Pending Booking','الحجوزات المعلقة')}}</button><button :class="{active:tab==='reservations'}" @click="tab='reservations'">{{tr('Booking Reservations','حجوزات مؤكدة')}}</button></nav><div class="bk-tools"><input v-model="search" :placeholder="tr('Search','بحث')"/><select v-model.number="perPage"><option :value="10">10 {{tr('per page','لكل صفحة')}}</option><option :value="15">15 {{tr('per page','لكل صفحة')}}</option><option :value="25">25 {{tr('per page','لكل صفحة')}}</option><option :value="50">50 {{tr('per page','لكل صفحة')}}</option></select></div><div v-if="error" class="bk-error">{{error}} <button @click="load">{{tr('Retry','إعادة المحاولة')}}</button></div><div class="bk-scroll"><table><thead><tr><th>ID</th><th>{{tr('Customer / Company','العميل / الشركة')}}</th><th>{{tr('Service','الخدمة')}}</th><th>{{tr('Vehicle','السيارة')}}</th><th>{{tr('Date','التاريخ')}}</th><th>{{tr('Total Price','السعر الإجمالي')}}</th><th>{{tr('Status','الحالة')}}</th><th>{{tr('Action','الإجراء')}}</th></tr></thead><tbody><tr v-if="loading"><td colspan="8" class="bk-empty">{{tr('Loading...','جاري التحميل...')}}</td></tr><template v-else><tr v-for="r in records" :key="r.id"><td>{{r.id}}</td><td>{{client(r)}}</td><td>{{tr('Rent A Car','تأجير سيارة')}}</td><td>{{r.car?.brand?.name}} {{r.car?.model?.name}} {{r.car?.model_year}} ({{r.car?.number}})</td><td>{{r.start_date}}</td><td>{{r.total}} {{r.currency}}</td><td>{{r.status}}</td><td><button class="bk-action" @click="router.push(`/rent/booking/${r.id}`)">◉ {{tr('View','عرض')}}</button></td></tr><tr v-if="!records.length"><td colspan="8" class="bk-empty">{{tr('No bookings found.','لا توجد حجوزات.')}}</td></tr></template></tbody></table></div><div class="bk-pagination"><span>{{meta.total}} {{tr('records','سجل')}}</span><div><button :disabled="page<=1" @click="page--">‹</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="page++">›</button></div></div></div></section></template>
<style scoped>.bk-page{padding:16px 20px;color:#0c2345}.bk-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}.bk-head h2{font-size:26px}.bk-primary{border:0;background:#6da2c3;border-radius:23px;color:white;padding:10px 24px;cursor:pointer}.bk-card{border:1px solid #dce3ea;border-radius:14px;background:white;overflow:hidden}.bk-tabs{display:flex;justify-content:center;gap:25px;padding:30px 10px 18px}.bk-tabs button{border:0;background:none;cursor:pointer;color:#9aa7bb;font-weight:650}.bk-tabs button.active{color:#0b2241}.bk-tools{display:flex;gap:15px;justify-content:space-between;padding:10px 20px 14px}.bk-tools input,.bk-tools select{height:32px;border:1px solid #d8e0e9;border-radius:8px;background:white;padding:0 10px;color:#19375a}.bk-tools input{width:min(290px,60%)}.bk-scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:12px}th,td{text-align:start;padding:14px 12px;border-top:1px solid #e3e9f0}th{color:#91a0b3;font-weight:500}td{white-space:nowrap}.bk-empty{text-align:center;color:#8b98a9;padding:44px}.bk-action{border:0;background:none;cursor:pointer;color:#1a3557}.bk-pagination{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;color:#5e7390}.bk-pagination>div{display:flex;gap:12px;align-items:center}.bk-pagination button{background:white;border:1px solid #e2e7ef;border-radius:7px;padding:5px 12px;cursor:pointer}.bk-pagination button:disabled{opacity:.4}.bk-error{padding:15px;color:#b91c1c}</style>
